"""Curated starter process pack, shipped by `turnstile init`.

GENERATED FILE — do not edit by hand. Regenerate from the repo's .processes/
pack with:

    uv run python scripts/gen_starters.py

STARTERS maps each definition's filename to its YAML content. STARTER_REGISTRY
is the registry.yaml content with the enforcement value replaced by the
sentinel __ENFORCEMENT__, which `init` substitutes with the selected mode.
"""


STARTERS: dict[str, str] = {
    "bug-fix.yaml": "name: bug-fix\ndescription: \"Structured bug fix workflow: reproduce, diagnose, fix, verify\"\nversion: \"1.3.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"starter-pack\", \"development\"]\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: bug_summary\n    description: \"Short description of the bug\"\n    required: true\n  - name: issue_id\n    description: \"Issue tracker ID\"\n    required: false\n    default: \"none\"\n  - name: test_command\n    description: \"Command to run the test suite. The default assumes pytest is on PATH in the gate's environment; pass your project's real invocation (e.g. 'uv run --group dev python -m pytest tests/') to avoid resolving a stray global pytest\"\n    required: false\n    default: \"pytest\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [reproduce]\n\n  - id: reproduce\n    description: \"Confirm the bug is reproducible before attempting a fix (writing a failing repro test here is encouraged)\"\n    transitions: [diagnose, abandoned]\n    on_enter:\n      validate:\n        - command: \"git log --oneline -5 2>/dev/null || echo 'not a git repo'\"\n          expect: not_empty\n          message: \"Recent commits (context for when the bug may have been introduced)\"\n          severity: info\n\n        - command: \"git status --short | head -20\"\n          expect: empty\n          message: \"Working tree should be clean before starting a fix\"\n          severity: warning\n\n  - id: diagnose\n    description: \"Understand the root cause before writing a fix\"\n    permissions:\n      edit: false\n    transitions: [fix, reproduce, abandoned]\n    on_enter:\n      validate:\n        - command: \"git diff --stat HEAD 2>/dev/null | tail -1 || echo 'no changes'\"\n          expect: not_empty\n          message: \"Files changed so far (investigation artifacts)\"\n          severity: info\n\n  - id: fix\n    description: \"Write the fix and any regression tests\"\n    transitions: [verify, diagnose]\n\n  - id: verify\n    description: \"Confirm the fix resolves the bug and doesn't introduce regressions\"\n    permissions:\n      edit: false\n    transitions: [done, fix]\n    on_enter:\n      validate:\n        - command: \"git diff --name-only 2>/dev/null | wc -l | tr -d ' '\"\n          expect: greater_than(0)\n          message: \"Must have changes to verify\"\n          severity: warning\n\n        - command: \"git diff --stat 2>/dev/null\"\n          expect: not_empty\n          message: \"Summary of changes\"\n          severity: info\n\n    on_exit:\n      validate:\n        - command: \"${test_command} 2>&1 | tail -1\"\n          expect: contains(\"passed\")\n          message: \"Test suite must pass\"\n\n        - command: \"${test_command} 2>&1 | tail -1 | grep -oP '\\\\d+(?= passed)'\"\n          expect: not_empty\n          message: \"Test count (verify no regressions)\"\n          severity: info\n\n  - id: done\n    type: terminal\n\n  - id: abandoned\n    type: terminal\n    description: \"Bug abandoned (not reproducible, already fixed, or not worth pursuing)\"\n",
    "code-review.yaml": "name: code-review\ndescription: \"Structured review of a changeset or pull request\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"starter-pack\", \"development\"]\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: branch\n    description: \"Branch or PR to review\"\n    required: true\n  - name: base_branch\n    description: \"Base branch to compare against\"\n    required: false\n    default: \"main\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [survey]\n\n  - id: survey\n    description: \"Understand the scope and context of the changes\"\n    permissions:\n      edit: false\n    transitions: [review]\n    on_enter:\n      validate:\n        - command: \"git log --oneline ${base_branch}..${branch} 2>/dev/null || echo 'branch not found'\"\n          expect: not_empty\n          message: \"Commits in this changeset\"\n          severity: info\n\n        - command: \"git diff --stat ${base_branch}...${branch} 2>/dev/null | tail -1 || echo 'no diff available'\"\n          expect: not_empty\n          message: \"Change summary (files changed, insertions, deletions)\"\n          severity: info\n\n        - command: \"git diff --name-only ${base_branch}...${branch} 2>/dev/null | head -30\"\n          expect: not_empty\n          message: \"Files changed\"\n          severity: info\n\n  - id: review\n    description: \"Read the code, check for issues, and note findings\"\n    permissions:\n      edit: false\n    transitions: [request_changes, approve, survey]\n\n  - id: request_changes\n    description: \"Changes are needed before this can be merged\"\n    permissions:\n      edit: false\n    transitions: [review]\n    on_enter:\n      validate:\n        - command: \"git diff --stat ${base_branch}...${branch} 2>/dev/null | tail -1 || echo 'no diff'\"\n          expect: not_empty\n          message: \"Current state of changes (has author addressed feedback?)\"\n          severity: info\n\n  - id: approve\n    type: terminal\n    description: \"Changes look good, ready to merge\"\n",
    "create-process.yaml": "name: create-process\ndescription: \"Design and validate a new turnstile process definition\"\nversion: \"1.0.0\"\n\nmetadata:\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n  notes:\n    - \"Back-transitions at every non-terminal state keep the workflow forgiving\"\n    - \"Info gates in understand state are the primary discovery mechanism\"\n    - \"Review gates check both validity and adherence to principles\"\n\nparameters:\n  - name: name\n    description: \"Name for the new process (becomes .processes/<name>.yaml)\"\n    required: true\n  - name: purpose\n    description: \"What workflow this process enforces\"\n    required: true\n\nstates:\n  - id: start\n    type: initial\n    transitions: [understand]\n\n  - id: understand\n    description: \"Survey existing processes, available tools, and design principles\"\n    transitions: [draft]\n    on_enter:\n      validate:\n        # Guard: don't overwrite an existing process\n        - command: \"test -f .processes/${name}.yaml && echo exists || echo available\"\n          expect: equals(\"available\")\n          message: \".processes/${name}.yaml must not already exist\"\n\n        # Progressive disclosure: surface what the author needs to\n        # design a good process, nothing more.\n\n        - command: \"uv run --package turnstile-cli turnstile list 2>&1\"\n          expect: not_empty\n          message: \"Existing processes (study patterns, avoid duplication)\"\n          severity: info\n\n        - command: \"for f in docs/principles/*.md; do head -1 \\\"$f\\\" | sed 's/# //'; done\"\n          expect: not_empty\n          message: \"Design principles to follow\"\n          severity: info\n\n        - command: \"echo 'empty | not_empty | equals(v) | not_equals(v) | contains(v) | starts_with(v) | ends_with(v) | matches(re) | greater_than(N) | less_than(N) | exit_code(N)'\"\n          expect: not_empty\n          message: \"Available expect expressions for validation gates\"\n          severity: info\n\n        - command: \"echo 'error: blocks transition | warning: logs, allows | info: always allows, surfaces context'\"\n          expect: not_empty\n          message: \"Severity levels\"\n          severity: info\n\n  - id: draft\n    description: \"Write .processes/${name}.yaml with states, transitions, and gates\"\n    transitions: [review, understand]\n    on_exit:\n      validate:\n        - command: \"test -f .processes/${name}.yaml && echo exists || echo missing\"\n          expect: equals(\"exists\")\n          message: \".processes/${name}.yaml must exist\"\n\n  - id: review\n    description: \"Validate the definition, dry-run it, and check principle adherence\"\n    transitions: [done, draft]\n    on_enter:\n      validate:\n        # Hard gate: must be structurally valid\n        - command: \"uv run --package turnstile-cli turnstile validate .processes/${name}.yaml 2>&1\"\n          expect: starts_with(\"Valid\")\n          message: \"Definition must pass schema validation\"\n\n        # Show dry run so the author can review the full structure\n        - command: \"uv run --package turnstile-cli turnstile dry-run --file .processes/${name}.yaml 2>&1\"\n          expect: not_empty\n          message: \"Dry run output (review states, transitions, and gates)\"\n          severity: info\n\n        # Principle checks: advisory, not blocking.\n        # A simple process may legitimately skip some of these.\n\n        # Progressive disclosure: info gates surface context for the agent\n        - command: \"grep -c 'severity: info' .processes/${name}.yaml\"\n          expect: greater_than(0)\n          message: \"Should have info-severity gates (progressive disclosure)\"\n          severity: warning\n\n        # Render don't record: gates should query systems, not trust self-reports\n        - command: \"grep -c 'command:' .processes/${name}.yaml\"\n          expect: greater_than(0)\n          message: \"Should have validation gates that query actual state\"\n          severity: warning\n\n        # Forgiveness: at least one state should offer multiple transitions\n        - command: \"grep 'transitions:' .processes/${name}.yaml | grep -c ','\"\n          expect: greater_than(0)\n          message: \"Should have at least one state with back-transitions\"\n          severity: warning\n\n  - id: done\n    type: terminal\n",
    "decision-record.yaml": "name: decision-record\ndescription: \"Structured decision-making process producing an auditable record of context, options, and rationale\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"general-purpose\", \"governance\"]\n  principles:\n    - render-dont-record\n    - portable-by-default\n    - single-process-single-document\n\nparameters:\n  - name: decision_title\n    description: \"Short title for the decision (e.g., 'Select auth provider', 'Hire vs contract for Q3')\"\n    required: true\n  - name: output_file\n    description: \"Path to write the decision record (e.g., docs/decisions/auth-provider.md)\"\n    required: false\n    default: \"none\"\n  - name: domain\n    description: \"Domain context (e.g., 'architecture', 'hiring', 'vendor selection', 'strategy')\"\n    required: false\n    default: \"general\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [frame]\n\n  - id: frame\n    description: \"Define the decision to be made. What is the question? What constraints apply (timeline, budget, technical, regulatory)? Who are the stakeholders? What would happen if no decision were made?\"\n    transitions: [gather, abandoned]\n    on_enter:\n      validate:\n        - command: \"echo 'Domain: ${domain}'\"\n          expect: not_empty\n          message: \"Decision domain context\"\n          severity: info\n\n  - id: gather\n    description: \"Research the available options. Collect evidence, precedents, and input. Identify at least two viable options; a decision with only one option is a ratification, not a decision.\"\n    transitions: [evaluate, frame, abandoned]\n\n  - id: evaluate\n    description: \"Assess each option against the constraints and criteria identified during framing. Document trade-offs explicitly: what do you gain and what do you give up with each option?\"\n    transitions: [decide, gather]\n    on_exit:\n      validate:\n        - command: 'test \"${output_file}\" = \"none\" && echo skip || (grep -qi option \"${output_file}\" 2>/dev/null && echo found || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Options should be documented before deciding\"\n          severity: warning\n\n  - id: decide\n    description: \"Commit to an option. Document the rationale: why this option over the alternatives. Include what would change your mind (reversal conditions).\"\n    transitions: [communicate, evaluate]\n    on_exit:\n      validate:\n        - command: 'test \"${output_file}\" = \"none\" && echo skip || (grep -qiE \"decision|rationale|chose|selected\" \"${output_file}\" 2>/dev/null && echo found || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Decision and rationale should be documented\"\n          severity: warning\n\n  - id: communicate\n    description: \"Update relevant artifacts, notify stakeholders, and create follow-up work items if needed. The decision is not complete until the people affected by it know about it.\"\n    transitions: [decided, deferred]\n\n  - id: decided\n    type: terminal\n    description: \"Decision made, documented, and communicated.\"\n\n  - id: deferred\n    type: terminal\n    description: \"Decision deferred. Conditions not yet met, more information needed, or timing not right.\"\n\n  - id: abandoned\n    type: terminal\n    description: \"Decision no longer needed (circumstances changed, question became moot).\"\n",
    "feature-development.yaml": "name: feature-development\ndescription: \"Standard feature development workflow\"\nversion: \"1.4.0\"\n\nmetadata:\n  author: \"matt\"\n  tags: [\"starter-pack\", \"development\"]\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: feature_name\n    description: \"Short name for the feature\"\n    required: true\n  - name: issue_id\n    description: \"Issue tracker ID (e.g., GitHub issue number)\"\n    required: false\n    default: \"none\"\n  - name: test_command\n    description: \"Command to run the test suite. The default assumes pytest is on PATH in the gate's environment; pass your project's real invocation (e.g. 'uv run --group dev python -m pytest tests/') to avoid resolving a stray global pytest\"\n    required: false\n    default: \"pytest\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [understand]\n\n  - id: understand\n    description: \"Survey the codebase and relevant context before writing code\"\n    permissions:\n      edit: false\n    transitions: [implement, abandoned]\n    on_enter:\n      validate:\n        # Progressive disclosure: surface just enough context to plan the work\n        # Double quotes: the shell must expand ${issue_id} (values arrive\n        # as env vars; single quotes would test the literal string)\n        - command: 'test \"${issue_id}\" != \"none\" && echo \"linked to ${issue_id}\" || echo \"no issue linked (consider passing issue_id)\"'\n          expect: not_empty\n          message: \"Issue linkage check\"\n          severity: info\n\n        - command: \"${test_command} 2>&1 | tail -1 || echo 'no test output'\"\n          expect: not_empty\n          message: \"Current test suite status (baseline before changes)\"\n          severity: info\n\n        - command: \"git status --short | head -20\"\n          expect: empty\n          message: \"Working tree should be clean before starting\"\n          severity: warning\n\n  - id: implement\n    description: \"Write the feature code\"\n    transitions: [test, understand, abandoned]\n\n  - id: test\n    description: \"Write and run tests verifying the changes\"\n    transitions: [review, implement]\n    on_enter:\n      validate:\n        # Render don't record: query git for what actually changed\n        - command: \"git diff --stat HEAD 2>/dev/null | tail -1 || echo 'no changes'\"\n          expect: not_empty\n          message: \"Changes since last commit\"\n          severity: info\n\n    on_exit:\n      validate:\n        # Hard gate: tests must pass\n        - command: \"${test_command} 2>&1 | tail -1\"\n          expect: contains(\"passed\")\n          message: \"Test suite must pass\"\n\n        # Check no test regressions\n        - command: \"${test_command} 2>&1 | tail -1 | grep -oP '\\\\d+(?= passed)'\"\n          expect: not_empty\n          message: \"Test count (verify no regressions)\"\n          severity: info\n\n  - id: review\n    description: \"Review the changes before finalizing\"\n    permissions:\n      edit: false\n    transitions: [done, implement]\n    on_enter:\n      validate:\n        # Render don't record: check what actually changed\n        - command: \"git diff --name-only 2>/dev/null | wc -l | tr -d ' '\"\n          expect: greater_than(0)\n          message: \"Must have uncommitted changes to review\"\n          severity: warning\n\n        - command: \"git diff --stat 2>/dev/null\"\n          expect: not_empty\n          message: \"Summary of changes\"\n          severity: info\n\n  - id: done\n    type: terminal\n\n  - id: abandoned\n    type: terminal\n    description: \"Feature abandoned (not worth pursuing, or superseded)\"\n",
    "peer-review.yaml": "name: peer-review\ndescription: \"Structured peer review with role handoff: submit, review, revise, accept\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"general-purpose\", \"quality\"]\n  principles:\n    - render-dont-record\n    - portable-by-default\n    - single-process-single-document\n\nparameters:\n  - name: artifact\n    description: \"What is being reviewed (e.g., 'API design doc', 'Q3 budget proposal', 'auth module refactor')\"\n    required: true\n  - name: artifact_path\n    description: \"Path to the artifact under review (file or directory)\"\n    required: false\n    default: \"none\"\n  - name: domain\n    description: \"Domain context (e.g., 'engineering', 'legal', 'finance', 'design')\"\n    required: false\n    default: \"general\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [prepare]\n\n  - id: prepare\n    role: submitter\n    description: \"Prepare the artifact for review. Ensure it is complete, meets submission criteria, and is ready for another party to evaluate.\"\n    agent_context:\n      guidance: |\n        You are preparing an artifact for peer review.\n        Ensure the artifact is complete and ready for evaluation.\n        Consider: is the scope clear? Are dependencies documented?\n        Is there enough context for a reviewer unfamiliar with the work?\n    transitions: [awaiting_review, abandoned]\n    on_exit:\n      validate:\n        - command: 'test \"${artifact_path}\" = \"none\" && echo skip || (test -e \"${artifact_path}\" && echo exists || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Artifact must exist if a path was specified\"\n          severity: warning\n\n  - id: awaiting_review\n    type: wait\n    role: reviewer\n    description: \"Artifact submitted for review. Waiting for reviewer to evaluate and provide feedback.\"\n    agent_context:\n      guidance: |\n        You are reviewing an artifact submitted by another party.\n        Evaluate it against the standards of the domain.\n        Provide specific, actionable feedback.\n        Decide: accept as-is, or request changes with clear guidance.\n    signal:\n      name: review_decision\n      required_fields:\n        - key: decision\n          description: \"Either 'accepted' or 'changes_requested'\"\n        - key: feedback\n          description: \"Reviewer comments and feedback\"\n    transitions: [accepted, revise]\n\n  - id: revise\n    role: submitter\n    description: \"Address reviewer feedback. Make the requested changes, then resubmit.\"\n    agent_context:\n      guidance: |\n        The reviewer has requested changes.\n        Review the feedback carefully and address each point.\n        When ready, resubmit for another round of review.\n    transitions: [awaiting_review, abandoned]\n\n  - id: accepted\n    type: terminal\n    description: \"Artifact accepted by reviewer.\"\n\n  - id: abandoned\n    type: terminal\n    description: \"Review abandoned (artifact withdrawn, no longer needed, or blocked).\"\n",
    "readme-update.yaml": "name: readme-update\ndescription: \"Update the project README to reflect the current state of the codebase\"\nversion: \"1.0.0\"\n\nmetadata:\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: reason\n    description: \"Why the README needs updating\"\n    required: true\n\nstates:\n  - id: start\n    type: initial\n    transitions: [audit]\n\n  - id: audit\n    description: \"Survey the codebase to discover what the README should cover\"\n    transitions: [update]\n    on_enter:\n      validate:\n        - command: \"test -f README.md && echo exists || echo missing\"\n          expect: equals(\"exists\")\n          message: \"README.md must exist\"\n\n        # Progressive disclosure: surface just enough for the agent to\n        # understand the current codebase without overwhelming it.\n        - command: \"ls packages/turnstile-core/src/turnstile_core/*.py | xargs -I{} basename {} .py | sort\"\n          expect: not_empty\n          message: \"Core modules\"\n          severity: info\n\n        - command: \"grep -oP 'async def \\\\K(process_\\\\w+)' packages/turnstile-mcp/src/turnstile_mcp/server.py | sort\"\n          expect: not_empty\n          message: \"MCP tools in source\"\n          severity: info\n\n        - command: \"uv run --package turnstile-cli turnstile --help 2>&1 | grep -A50 'Commands:'\"\n          expect: not_empty\n          message: \"CLI commands\"\n          severity: info\n\n        - command: \"uv run --group dev python -m pytest packages/turnstile-core/tests/ packages/turnstile-cli/tests/ -q --no-header 2>&1 | tail -1\"\n          expect: contains(\"passed\")\n          message: \"Test suite status\"\n          severity: info\n\n  - id: update\n    description: \"Edit README.md to reflect what the audit discovered\"\n    transitions: [verify, audit]\n    on_exit:\n      validate:\n        # Render don't record: check the actual git state rather than\n        # trusting the agent to say \"yes I changed it\".\n        - command: \"git diff --name-only README.md | wc -l | tr -d ' '\"\n          expect: greater_than(0)\n          message: \"README.md must have uncommitted changes\"\n\n  - id: verify\n    description: \"Check README completeness against the actual codebase\"\n    transitions: [done, update]\n    on_enter:\n      validate:\n        # Render don't record: compare source of truth (code) against the\n        # docs rather than asking the agent to self-certify. The README is\n        # deliberately a summary; the full surface lives in\n        # docs/reference.md, so completeness is checked there.\n        - command: \"grep -oP 'async def \\\\K(process_\\\\w+)' packages/turnstile-mcp/src/turnstile_mcp/server.py | while read tool; do grep -q \\\"$tool\\\" docs/reference.md || echo \\\"$tool\\\"; done\"\n          expect: empty\n          message: \"All MCP tools must be documented in docs/reference.md\"\n\n        - command: \"for cmd in validate list status graph dry-run schema check-completed analytics init-package; do grep -q \\\"turnstile $cmd\\\" docs/reference.md || echo \\\"$cmd\\\"; done\"\n          expect: empty\n          message: \"All CLI commands must be documented in docs/reference.md\"\n\n        - command: \"grep -q 'docs/reference.md' README.md && echo linked || echo missing\"\n          expect: equals(\"linked\")\n          message: \"README must link to the full reference\"\n\n        - command: \"grep -c '^## ' README.md\"\n          expect: greater_than(5)\n          message: \"README should have at least 6 top-level sections\"\n          severity: warning\n\n  - id: done\n    type: terminal\n",
    "release.yaml": "name: release\ndescription: \"Prepare, validate, and ship a versioned release\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"starter-pack\", \"operations\"]\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: version\n    description: \"Version number to release (e.g., 1.2.0)\"\n    required: true\n  - name: base_branch\n    description: \"Branch to release from\"\n    required: false\n    default: \"main\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [prepare]\n\n  - id: prepare\n    description: \"Review what will be in this release\"\n    permissions:\n      edit: false\n    transitions: [validate]\n    on_enter:\n      validate:\n        - command: \"git log --oneline $(git describe --tags --abbrev=0 2>/dev/null || echo HEAD~10)..HEAD 2>/dev/null | head -20\"\n          expect: not_empty\n          message: \"Commits since last tag (what's in this release)\"\n          severity: info\n\n        - command: \"git tag -l 2>/dev/null | tail -5\"\n          expect: not_empty\n          message: \"Recent tags (verify version numbering)\"\n          severity: info\n\n        - command: \"git status --short\"\n          expect: empty\n          message: \"Working tree must be clean before release\"\n          severity: warning\n\n  - id: validate\n    description: \"Run the full test suite and any pre-release checks\"\n    permissions:\n      edit: false\n    transitions: [tag, prepare]\n    on_exit:\n      validate:\n        - command: \"git diff --name-only HEAD 2>/dev/null | wc -l | tr -d ' '\"\n          expect: equals(\"0\")\n          message: \"All changes must be committed before tagging\"\n          severity: warning\n\n  - id: tag\n    description: \"Create the release tag and finalize\"\n    transitions: [done, validate]\n    on_enter:\n      validate:\n        - command: \"git tag -l v${version} 2>/dev/null | wc -l | tr -d ' '\"\n          expect: equals(\"0\")\n          message: \"Tag v${version} must not already exist\"\n\n        - command: \"git branch --show-current 2>/dev/null\"\n          expect: not_empty\n          message: \"Current branch (confirm you're on the right one)\"\n          severity: info\n\n  - id: done\n    type: terminal\n    description: \"Release v${version} is tagged and ready to ship\"\n",
    "scientific-method.yaml": "name: scientific-method\ndescription: \"Structured investigation using the scientific method: observe, hypothesize, test, conclude\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"general-purpose\", \"investigation\"]\n  principles:\n    - render-dont-record\n    - portable-by-default\n    - single-process-single-document\n\nparameters:\n  - name: observation\n    description: \"The initial observation or phenomenon prompting investigation\"\n    required: true\n  - name: output_file\n    description: \"Path to write findings (e.g., docs/investigations/topic.md)\"\n    required: false\n    default: \"none\"\n  - name: domain\n    description: \"Domain context for the investigation (e.g., 'codebase', 'market research', 'compliance')\"\n    required: false\n    default: \"general\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [observe]\n\n  - id: observe\n    description: \"Gather and document observations about the phenomenon. What do you see? What data is available? What are the relevant conditions?\"\n    transitions: [question, abandoned]\n    on_enter:\n      validate:\n        - command: \"echo 'Domain: ${domain}'\"\n          expect: not_empty\n          message: \"Investigation domain context\"\n          severity: info\n\n  - id: question\n    description: \"Formulate a specific, testable question from the observations. A good question is narrow, measurable, and answerable with available methods.\"\n    transitions: [hypothesize, observe, abandoned]\n\n  - id: hypothesize\n    description: \"Propose a testable explanation that answers the question. State it as a prediction: if the hypothesis is true, then [expected outcome] when [test condition].\"\n    transitions: [experiment, question]\n    on_exit:\n      validate:\n        - command: 'test \"${output_file}\" = \"none\" && echo skip || (grep -qi hypothes \"${output_file}\" 2>/dev/null && echo found || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Hypothesis should be documented before testing\"\n          severity: warning\n\n  - id: experiment\n    description: \"Design and execute a test of the hypothesis. Define what you will measure, how you will measure it, and what results would support or refute the hypothesis.\"\n    transitions: [analyze, hypothesize]\n\n  - id: analyze\n    description: \"Examine the results of the experiment. Do they support, refute, or fail to resolve the hypothesis? Are there confounding factors or alternative explanations?\"\n    transitions: [conclude, hypothesize, experiment]\n\n  - id: conclude\n    description: \"Draw conclusions. Summarize findings, state whether the hypothesis was supported or refuted, identify limitations, and propose follow-up questions.\"\n    transitions: [supported, refuted, inconclusive]\n    on_exit:\n      validate:\n        - command: 'test \"${output_file}\" = \"none\" && echo skip || (test -f \"${output_file}\" && echo exists || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Output file must exist if one was specified\"\n          severity: warning\n\n  - id: supported\n    type: terminal\n    description: \"Hypothesis supported by evidence. Findings documented.\"\n\n  - id: refuted\n    type: terminal\n    description: \"Hypothesis refuted by evidence. Findings documented.\"\n\n  - id: inconclusive\n    type: terminal\n    description: \"Results inconclusive. May need refined hypothesis, better experiment design, or more data.\"\n\n  - id: abandoned\n    type: terminal\n    description: \"Investigation abandoned (question answered elsewhere, not worth pursuing, or blocked)\"\n",
    "security-review.yaml": "extends: peer-review\nname: security-review\ndescription: \"Security-focused peer review with OWASP and threat modeling guidance\"\nversion: \"1.0.0\"\n\noverrides:\n  patch_states:\n    - id: prepare\n      agent_context:\n        guidance: |\n          You are preparing an artifact for security review.\n          Ensure the artifact includes: architecture diagrams, data flow,\n          authentication/authorization boundaries, and any external dependencies.\n          Document known security assumptions and trust boundaries.\n        reference_files:\n          - docs/security/threat-model.md\n          - docs/security/checklist.md\n\n    - id: awaiting_review\n      role: security_reviewer\n      agent_context:\n        guidance: |\n          You are conducting a security review.\n          Evaluate against OWASP Top 10, focusing on:\n          - Injection vulnerabilities (SQL, command, XSS)\n          - Authentication and session management\n          - Access control and authorization\n          - Data exposure and encryption\n          - Input validation and output encoding\n          - Dependency vulnerabilities\n          Flag findings by severity: critical, high, medium, low.\n        reference_files:\n          - docs/security/threat-model.md\n          - docs/security/checklist.md\n        tools:\n          - web_search\n          - grep\n\n    - id: revise\n      agent_context:\n        guidance: |\n          The security reviewer has identified findings.\n          Address each finding by severity, starting with critical.\n          For each finding: fix the vulnerability, add a test or\n          validation that prevents regression, and document the fix.\n",
    "spike.yaml": "name: spike\ndescription: \"Time-boxed investigation with a written outcome\"\nversion: \"1.1.0\"\n\nmetadata:\n  author: \"turnstile\"\n  tags: [\"starter-pack\", \"research\"]\n  principles:\n    - progressive-disclosure\n    - render-dont-record\n    - single-process-single-document\n\nparameters:\n  - name: question\n    description: \"The question this spike aims to answer\"\n    required: true\n  - name: output_file\n    description: \"Path to write findings (e.g., docs/spikes/my-topic.md)\"\n    required: false\n    default: \"none\"\n\nstates:\n  - id: start\n    type: initial\n    transitions: [investigate]\n\n  - id: investigate\n    description: \"Research the question, explore options, gather evidence\"\n    transitions: [write_up, abandoned]\n    on_enter:\n      validate:\n        - command: \"git status --short | head -20\"\n          expect: not_empty\n          message: \"Working tree status (any prior work in progress?)\"\n          severity: info\n\n  - id: write_up\n    description: \"Document findings, recommendation, and next steps\"\n    transitions: [done, investigate]\n    on_enter:\n      validate:\n        - command: \"git diff --stat HEAD 2>/dev/null | tail -1 || echo 'no changes'\"\n          expect: not_empty\n          message: \"Changes made during investigation\"\n          severity: info\n    on_exit:\n      validate:\n        - command: 'test \"${output_file}\" = \"none\" && echo skip || (test -f \"${output_file}\" && echo exists || echo missing)'\n          expect: not_equals(\"missing\")\n          message: \"Output file must exist if one was specified\"\n          severity: warning\n\n  - id: done\n    type: terminal\n    description: \"Spike complete, findings documented\"\n\n  - id: abandoned\n    type: terminal\n    description: \"Spike abandoned (question answered early, or not worth pursuing)\"\n",
}

STARTER_REGISTRY: str = "version: '1.0'\nlocal:\n- feature-development\n- create-process\n- readme-update\n- bug-fix\n- code-review\n- release\n- spike\n- scientific-method\n- decision-record\n- peer-review\n- security-review\nsettings:\n  state_dir: .process-state\n  require_override_reason: true\n  log_retention_days: 90\n  enforcement: __ENFORCEMENT__\n\n  notifications:\n    # ${var} references are expanded by the shell from environment variables\n    # (name, instance_id, state, step, user, reason). Use double quotes so the\n    # shell expands them; single quotes would emit the literal text.\n    on_complete: 'echo \"[COMPLETE] ${name} (${instance_id}) finished at ${state}\" >> .process-state/log.txt'\n    on_override: 'echo \"[OVERRIDE] ${name} (${instance_id}): ${step} skipped by ${user} - ${reason}\" >> .process-state/log.txt'\n"
